@@ -1,13 +1,18 @@
 export type RetryOptions = { attempts: number; baseMs: number };

+const MAX_JITTER_MS = 50;
+
 const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

+function backoff(baseMs: number, attempt: number): number {
+  return baseMs * 2 ** attempt + Math.random() * MAX_JITTER_MS;
+}
+
 export async function retry<T>(fn: () => Promise<T>, opts: RetryOptions): Promise<T> {
   let lastErr: unknown;
   for (let i = 0; i < opts.attempts; i++) {
     try {
       return await fn();
     } catch (err) {
       lastErr = err;
-      if (i < opts.attempts - 1) await sleep(opts.baseMs * 2 ** i);
+      if (i < opts.attempts - 1) await sleep(backoff(opts.baseMs, i));
     }
   }
